-- Baseline: the schema as it stood when migrations were introduced.
--
-- Every table is created IF NOT EXISTS on purpose. Hosted databases that
-- predate this file were set up with `drizzle-kit push` and already have all
-- of these tables, with data in them. Running the baseline there is a no-op
-- that only records itself in drizzle.__drizzle_migrations, after which later
-- migrations apply normally. On an empty database it creates everything.
-- Do not edit this file after it has been applied anywhere: the migrator
-- records a hash of its contents.
CREATE TABLE IF NOT EXISTS "analytics_events" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" text,
	"event_type" text,
	"properties" jsonb,
	"session_id" text,
	"created_at" timestamp DEFAULT now()
);
--> statement-breakpoint
